12	import { describe, it, expect, afterEach, vi } from "vitest";
13	import { getWebSocketCtor } from "../src/cli/websocket.js";
14	
15	describe("cli/websocket polyfill", () => {
16	  afterEach(() => {
17	    vi.unstubAllGlobals();
18	  });
19	
20	  it("returns a WebSocket constructor", () => {
21	    const WS = getWebSocketCtor();
22	    expect(typeof WS).toBe("function");
23	  });
24	
25	  it("prefers globalThis.WebSocket when available", () => {
26	    class FakeWS { constructor(_url: string) { /* noop */ } }
27	    vi.stubGlobal("WebSocket", FakeWS);
28	
29	    const WS = getWebSocketCtor();
30	    expect(WS).toBe(FakeWS);
31	  });
32	
33	  it("falls back to ws package when globalThis.WebSocket is undefined", () => {
34	    // Simulate Node < 22 where globalThis.WebSocket does not exist
35	    vi.stubGlobal("WebSocket", undefined);
36	
37	    const WS = getWebSocketCtor();
38	    expect(typeof WS).toBe("function");
39	    // The fallback should NOT be the (now-undefined) global
40	    expect(WS).not.toBe(undefined);
41	  });
42	
43	  it("can establish a real WebSocket connection via the ws fallback", async () => {
44	    // Force the fallback path to simulate Node < 22
45	    vi.stubGlobal("WebSocket", undefined);
46	
47	    const { WebSocketServer } = await import("ws");
48	    const { createServer } = await import("node:http");
49	
50	    const server = createServer();
51	    const wss = new WebSocketServer({ server });
52	    let serverReceived: string | undefined;
53	
54	    wss.on("connection", (ws) => {
55	      ws.on("message", (data) => {
56	        serverReceived = data.toString();
57	        ws.send("pong");
58	      });
59	    });
60	
61	    await new Promise<void>((resolve) => server.listen(0, resolve));
62	    const port = (server.address() as { port: number }).port;
63	
64	    try {
65	      const WS = getWebSocketCtor();
66	      const ws = new WS(`ws://localhost:${port}`);
67	      const result = await new Promise<string>((resolve, reject) => {
68	        const timeout = setTimeout(() => reject(new Error("timeout")), 5000);
69	        ws.onopen = () => {
70	          ws.send("ping");
71	        };
72	        ws.onmessage = (event: MessageEvent) => {
73	          clearTimeout(timeout);
74	          resolve(event.data as string);
75	          ws.close();
76	        };
77	        ws.onerror = () => {
78	          clearTimeout(timeout);
79	          reject(new Error("WebSocket error"));
80	        };
81	      });
82	
83	      expect(result).toBe("pong");
84	      expect(serverReceived).toBe("ping");
85	    } finally {
86	      wss.close();
87	      server.close();
88	    }
89	  });
90	});

